export interface Kit3D {
  ground: string;
  groundAlt: string;
  path: string;
  water: string;
  sky: [string, string];
  fog: string;
  sun: string;
  trees: string[];
  scatter: string[];
  rocks: string[];
  /** Zone.landmark key -> ASSETS3D key. Unknown landmark keys: use landmarks.shrine. */
  landmarks: Record<string, string>;
  /** NpcSpec.archetype -> ASSETS3D key. Unknown archetypes: use npcBodies.kid. */
  npcBodies: Record<string, string>;
  companion: string;
  ambience: 'pollen' | 'stars' | 'sand' | 'bubbles' | 'sparks' | 'fireflies';
  /** Extra set dressing for this template (buildings, props), placed around zones. */
  props?: string[];
}

