/** Resolve a landmark key for a template, falling back to that template's shrine. */
export function landmarkAsset(template: TemplateId, key: string): Asset3D {
  const k = KITS[template].landmarks[key] ?? KITS[template].landmarks.shrine;
  return ASSETS3D[k] ?? ASSETS3D['landmark.shrine'];
}

/** Resolve an NPC archetype to a body for a template, falling back to 'kid'. */
export function npcAsset(template: TemplateId, archetype: string): Asset3D {
  const k = KITS[template].npcBodies[archetype] ?? KITS[template].npcBodies.kid;
  return ASSETS3D[k] ?? ASSETS3D['npc.kid'];
}
